/*
 * Compile with: gcc -o getattr_example getattr_example.c -pthread
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define STACK_SIZE_REQUEST (1024 * 1024)

void* thread_func(void* arg) {
    printf("\nWorker thread running.\n");
    // Sleep briefly to ensure main thread has time to inspect attributes
    sleep(1);
    return NULL;
}

int main() {
    pthread_t thread_id;
    pthread_attr_t attr_obj;
    pthread_attr_t runtime_attr;
    int s;

    // 1. Initialize attribute object and set a desired stack size
    if ((s = pthread_attr_init(&attr_obj)) != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", s);
        return 1;
    }
    pthread_attr_setstacksize(&attr_obj, STACK_SIZE_REQUEST);

    // 2. Create the thread
    if ((s = pthread_create(&thread_id, &attr_obj, thread_func, NULL)) != 0) {
        fprintf(stderr, "Error creating thread: %d\n", s);
        pthread_attr_destroy(&attr_obj);
        return 1;
    }
    printf("Thread created successfully (ID: %lu).\n", (unsigned long)thread_id);
    printf("Requested stack size: %zu bytes.\n", (size_t)STACK_SIZE_REQUEST);

    // 3. Get actual runtime attributes using pthread_getattr_np
    if ((s = pthread_getattr_np(thread_id, &runtime_attr)) != 0) {
        fprintf(stderr, "Error getting thread attributes (pthread_getattr_np): %d\n", s);
    } else {
        size_t actual_stack_size;
        void *stack_addr;
        int detach_state;

        pthread_attr_getstacksize(&runtime_attr, &actual_stack_size);
        pthread_attr_getstackaddr(&runtime_attr, &stack_addr);
        pthread_attr_getdetachstate(&runtime_attr, &detach_state);

        printf("--- Runtime Attributes ---\n");
        printf("Actual Stack Size: %zu bytes (usually aligned).\n", actual_stack_size);
        printf("Stack Address: %p\n", stack_addr);
        printf("Detach State: %s\n", (detach_state == PTHREAD_CREATE_JOINABLE ? "JOINABLE" : "DETACHED"));

        // 4. Clean up the runtime attribute object
        pthread_attr_destroy(&runtime_attr);
    }

    // 5. Wait for the thread to finish
    pthread_join(thread_id, NULL);
    // 6. Clean up the creation attribute object
    pthread_attr_destroy(&attr_obj);

    return 0;
}
